var KEY = "actes-lang";
var norm = (s) => s.replace(/[\u064B-\u0652\u200f\u200e]/g, "").replace(/[\u0623\u0625\u0622\u0671]/g, "ا").replace(/\s+/g, " ").trim();
var AR = /[\u0600-\u06FF]/;
var ATTRS = [
	"placeholder",
	"aria-label",
	"title",
	"alt"
];
var esc = (s) => s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
var B = "(^|[^\\u0600-\\u06FF])";
var E = "(?=$|[^\\u0600-\\u06FF])";
function prepare(source) {
	const normalized = {};
	for (const [key, value] of Object.entries(source)) normalized[norm(key)] = value;
	return {
		normalized,
		words: Object.entries(normalized).filter(([key]) => key.includes(" ") || key.length >= 2).sort((a, b) => b[0].length - a[0].length).map(([arabic, translated]) => [new RegExp(B + esc(arabic) + E, "g"), translated])
	};
}
var dictionaries = {
	en: prepare(en_dict_default),
	zh: prepare(zh_dict_default)
};
